schema.raw:
-- Create dimension tables for machines, buffers, and stations
CREATE TABLE machines (
    id TEXT PRIMARY KEY,
    name TEXT NOT NULL,
    type TEXT NOT NULL
);

CREATE TABLE buffers (
    id TEXT PRIMARY KEY,
    capacity INTEGER NOT NULL,
    before TEXT NOT NULL,
    after TEXT NOT NULL
);

CREATE TABLE stations (
    id TEXT PRIMARY KEY,
    processing_time_s INTEGER NOT NULL,
    availability_pct REAL,
    mttr_s INTEGER,
    power_working_kw REAL,
    power_idle_kw REAL
);

-- Create tag_map to map sensor tags to physical quantities
CREATE TABLE tag_map (
    tag_id TEXT PRIMARY KEY,
    machine_id TEXT NOT NULL,
    signal TEXT NOT NULL,
    unit TEXT NOT NULL,
    register TEXT NOT NULL,
    scale REAL NOT NULL
);

-- Create raw ingest table to store raw payloads
CREATE TABLE raw_ingest (
    ingested_at TIMESTAMPTZ NOT NULL,
    source TEXT NOT NULL,
    payload JSONB NOT NULL
);

-- Create ingest_watermark to track the latest event time for each source
CREATE TABLE ingest_watermark (
    source TEXT PRIMARY KEY,
    max_event_ts TIMESTAMPTZ
);

-- Create fact tables for events and samples with time-series data
CREATE TABLE events (
    ts TIMESTAMPTZ NOT NULL,
    machine_id TEXT NOT NULL,
    reason_code TEXT,
    duration_s DOUBLE PRECISION,
    energy_kwh DOUBLE PRECISION
);

CREATE TABLE samples (
    ts TIMESTAMPTZ NOT NULL,
    machine_id TEXT NOT NULL,
    tag TEXT NOT NULL,
    value DOUBLE PRECISION
);

-- Create views over raw_ingest to expose typed fact tables
CREATE VIEW events_view AS
SELECT T1.ingested_at AS ts, T1.payload->>'machine_id' AS machine_id, T1.payload->>'reason_code' AS reason_code, T1.payload->>'duration_s' AS duration_s, T1.payload->>'energy_kwh' AS energy_kwh FROM raw_ingest AS T1 WHERE T1.payload->>'type' = 'event';

CREATE VIEW samples_view AS
SELECT T1.ingested_at AS ts, T1.payload->>'machine_id' AS machine_id, T1.payload->>'tag' AS tag, T1.payload->>'value' AS value FROM raw_ingest AS T1 WHERE T1.payload->>'type' = 'sample';

